head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.param2 = "";
scwin.param3 = "";
scwin.cnt = 0;
scwin.crud = "";
scwin.prevRow = -1;

// 종목기준명 등록 호출

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    try {
        // 삭제 $c.cm.PanelToGroupBox(panel_1);

        $c.cm.ins_combo_set(dtl_CodRes, "ULDINS91200.xml", $c.stf.info("SCREN_PROCS_TP_CD_01"), "03478", "SEL"); // 03478 - ELS DLS 구분  ELS_DLS_TP_CD  2013.11.25 ELSDLS구분코드 변경      
        txb_BAS_ISU_NM.hide();
        btn_search.hide();
        const sd = $c.frame.path("../").scwin.vScrenID;
        if (sd === "ULDINS10100.xml" || sd === "ULDINS10900.xml" || sd === "ULDINS15100.xml" || sd === "ULDINS16200.xml" ||
            sd === "ULDINS10800.xml" || sd === "ULDINS16100.xml") {
            // 채권 접수 , 채권관리 , CP전자단기사채 접수 ,  CP전자단기사채 관리
            // CD 접수,관리
            cmb_ELS_DLS_TP_CD.hide();
            label_8.hide();

            // 보류 $c.cm.setColumnProp(grd_Grid, "ELS_DLS_NM", "Show", false);

            // 보류 $c.cm.setColumnProp(grd_Grid, "BAS_ISU_NM", "width", "200");
            scwin.param3 = "0";
        } else if (sd === "ULDINS10200.xml" || sd === "ULDINS15200.xml") {
            const ELS_DLS_TP_CD = $c.frame.path("../").cmb_ELS_DLS_TP_CD.getValue();
            // alert(ELS_DLS_TP_CD);
            // elsdls 접수 , 관리 
            cmb_ELS_DLS_TP_CD.show("");
            label_8.show("");

            // 보류 $c.cm.setColumnProp(grd_Grid, "ELS_DLS_NM", "Show", true);
            scwin.param3 = "1";
        }
        const arrPar = new Array();
        const parentWin = $c.frame.path("../");

        scwin.fn_GetPar = parentWin.scwin.fn_GetParam;

        if (scwin.fn_GetPar !== undefined) {

            scwin.fn_GetPar(arrPar);
            scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : "");
            scwin.param2 = ((arrPar.length >= 1) && (arrPar[1] !== undefined) ? arrPar[1] : "");
        }
        // alert(param2);
        scwin.ins_search(scwin.param1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.onpageload" });
    }
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.dts_List_OnLoadCompleted = async function(e) {
    try {
        if (rowcount === 0) {

            $c.cm.fn_CtrlBtn("no_data");
        } else {
            cmb_ELS_DLS_TP_CD.setValue(dtl_ListRes.getCellData(dtl_ListRes.getRowPosition(), "ELS_DLS_TP_CD"));
        }
        scwin.cnt = rowcount;
        // 삭제 $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91200.dts_List_OnLoadCompleted" });
    }
};

scwin.dts_List_OnLoadError = function(e) {
    try {
        $c.win.alert(dtl_ListRes);
        scwin.cnt = 0;
        // 삭제 $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

        $c.cm.fn_CtrlBtn("no_data");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.dts_List_OnLoadError" });
    }
};

scwin.btn_modify_onclick = function(e) {
    try {
        scwin.ins_process("03");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_modify_onclick" });
    }
};

scwin.trs_modify_OnSuccess = function(e) {
    try {
        alert($c.stf.getMessageParam("MSG-A001", "종목기준명 수정"));
        scwin.ins_search(scwin.param1);
        // frame.CloseFrame();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.trs_modify_OnSuccess" });
    }
};

scwin.trs_modify_OnFail = function(e) {
    try {
        alert_tr_error(trs_modify);
        scwin.ins_search(scwin.param1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.trs_modify_OnFail" });
    }
};

scwin.trs_save_OnSuccess = function(e) {
    try {
        alert($c.stf.getMessageParam("MSG-A001", "종목기준명 등록"));
        scwin.ins_search(scwin.param1);
        // frame.CloseFrame();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.trs_save_OnSuccess" });
    }
};

scwin.trs_save_OnFail = function(e) {
    try {
        alert_tr_error(trs_save);
        scwin.ins_search(scwin.param1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.trs_save_OnFail" });
    }
};

scwin.trs_remove_OnSuccess = function(e) {
    try {
        alert($c.stf.getMessageParam("MSG-A001", "종목기준명 삭제"));
        scwin.ins_search(scwin.param1);
        // frame.CloseFrame();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.trs_remove_OnSuccess" });
    }
};

scwin.trs_remove_OnFail = function(e) {
    try {
        alert_tr_error(trs_remove);
        scwin.ins_search(scwin.param1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.trs_remove_OnFail" });
    }
};

scwin.btn_save_onclick = function(e) {
    try {
        scwin.ins_process("02");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_save_onclick" });
    }
};

scwin.btn_delete_onclick = function(e) {
    try {
        scwin.ins_remove();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_delete_onclick" });
    }
};

scwin.btn_close_onclick = async function(e) {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91200.btn_close_onclick" });
    }
};

scwin.btn_modify_onclick = function(e) {
    try {
        scwin.ins_process("03");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_modify_onclick" });
    }
};

scwin.btn_search_onclick = function(e) {
    try {
        scwin.ins_search(scwin.param1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_search_onclick" });
    }
};

scwin.dtl_CodRes_OnLoadCompleted = function(e) {
    // alert('dtl_CodRes.OnLoadCompleted('+rowcount+')');

};

scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        const BAS_ISU_NM = dtl_ListRes.getCellData(row, "BAS_ISU_NM");
        const BAS_ISU_ABBRV = dtl_ListRes.getCellData(row, "BAS_ISU_ABBRV");
        const BAS_ISU_ENG_NM = dtl_ListRes.getCellData(row, "BAS_ISU_ENG_NM");
        const BAS_ISU_ENG_ABBRV = dtl_ListRes.getCellData(row, "BAS_ISU_ENG_ABBRV");

        // ??$c.frame.path("../").ins_popupRtn_val4(BAS_ISU_NM, BAS_ISU_ABBRV, BAS_ISU_ENG_NM, BAS_ISU_ENG_ABBRV);
        $c.cm.ins_popupRtn_val4(BAS_ISU_NM, BAS_ISU_ABBRV, BAS_ISU_ENG_NM, BAS_ISU_ENG_ABBRV);

        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91200.grd_Grid_OnDblClick" });
    }
};

scwin.btn_new_onclick = function(e) {
    try {
        scwin.new();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_new_onclick" });
    }
};

scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        dtl_ListRes.undoRow(scwin.prevRow);
        scwin.prevRow = row;

        $c.cm.fn_CtrlBtn("update");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.dts_List_OnRowPosChanged" });
    }
};

scwin.btn_isunm_confirm_onclick = function(e) {
    try {
        $c.cm.ins_popupOpen("", "", "ULDINS90600", "주권 종목코드", "730", "505");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.btn_isunm_confirm_onclick" });
    }
};

scwin.grd_Grid_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.grd_Grid_OnDblClick(rowIndex, columnId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91200.grd_Grid_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/********************************************** 
 * 함수명   : ins_process
 * 설명       : 종목기준명 저장 , 수정하기   . screenProcsTpCd 02,03
 ***********************************************/
scwin.ins_process = async function(screenProcsTpCd) {
    // alert("dts_Out.Text " +dts_Out.Text);
    // alert("dts_Out.ISUR_CD " +dts_Out.NameValue(dts_Out.RowPosition,"ISUR_NM"));
    if (scwin.cnt === 0) {
        // fn_SetHeader() ; 

    } else {
        if (!$c.cp.isModified(dts_List)) {
            alert("변경된 데이터가 없습니다.");
            return;
        }
    }
    if (txb_NEW_BAS_ISU_NM.getValue() === "" || txb_NEW_BAS_ISU_NM.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "한글기준명"));

        txb_NEW_BAS_ISU_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_NEW_BAS_ISU_NM, 60, "한글기준명")) {

        txb_NEW_BAS_ISU_NM.focus();
        return false;
    }
    if (txb_BAS_ISU_ABBRV.getValue() === "" || txb_BAS_ISU_ABBRV.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "한글기준약명"));

        txb_BAS_ISU_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ABBRV, 20, "한글기준약명")) {

        txb_BAS_ISU_ABBRV.focus();
        return false;
    }
    if (txb_BAS_ISU_ENG_NM.getValue() === "" || txb_BAS_ISU_ENG_NM.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "영문기준명"));

        txb_BAS_ISU_ENG_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ENG_NM, 60, "영문기준명")) {

        txb_BAS_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_BAS_ISU_ENG_ABBRV.getValue() === "" || txb_BAS_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "영문기준약명"));

        txb_BAS_ISU_ENG_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ENG_ABBRV, 20, "영문기준약명")) {

        txb_BAS_ISU_ENG_ABBRV.focus();
        return false;
    }

    // alert(getObjectValue(cmb_ELS_DLS_TP_CD));

    // ELSDLS구분코드 필수
    if (scwin.param3 === "1" && cmb_ELS_DLS_TP_CD.getValue() === "") {
        alert("ELS/DLS, DLS/DLB구분이 선택되지 않았습니다.");

        cmb_ELS_DLS_TP_CD.focus();
        return false;
    }
    if (scwin.cnt === 0) {

    } else {
        if (screenProcsTpCd === "02") {
            // 등록시 중복체크 
            if (scwin.dup() === false) {
                alert("한글기준명 중복입니다.");
                return;
            }
        }
    }
    trs_save.KeyName = "toinb_dataid4";

    // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_save",
        action : "/CmmInfoAction.do",
        ref : "dts_List",
        target : "trs_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/********************************************** 
 * 함수명   : ins_remove
 * 설명       : 종목기준명 삭제하기   . screenProcsTpCd 04
 ***********************************************/
scwin.ins_remove = async function() {
    if (dtl_ListRes.getRowCount() === 1) {
        alert("정보가 1건입니다. 삭제불가입니다. 수정만 가능합니다.");
        return;
    }
    const rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ListDelete.insertRow();
        dts_ListDelete.setCellData(1, "ISUR_CD", dtl_ListRes.getCellData(dtl_ListRes.getRowPosition(), "ISUR_CD"));
        dts_ListDelete.setCellData(1, "BAS_ISU_NM", dtl_ListRes.getCellData(dtl_ListRes.getRowPosition(), "BAS_ISU_NM"));

        // alert("dts_ListDelete.ISUR_CD "+ dts_ListDelete.NameValue(dts_ListDelete.RowPosition,"ISUR_CD"));

        trs_remove.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_trs_remove",
            action : "/CmmInfoAction.do",
            ref : "dts_ListDelete",
            target : "trs_remove=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 종목기준명 조회하기 .
 ***********************************************/
scwin.ins_search = async function(isurcd) {debugger;
/*
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)


*/

dma_ListReq.set("SCREN_ID", "ULDINS91200.xml");
dma_ListReq.set("SCREN_PROCES_TP_CD", $c.stf.info("SCREN_PROCS_TP_CD_01"));
dma_ListReq.set("param01", isurcd);
dma_ListReq.set("param02", scwin.param3);

    const reqMap = dma_ListReq.getJSON();
    // const res = await $c.sbm.execute(sbm_dts_List, reqMap);

    // dtl_ListRes.setJSON(res);
    // await scwin.dts_List_OnLoadCompleted();

    // 임시 데이터
    await dtl_ListRes.setData(["","","(주)삼성산업","삼성산업","삼성산업","삼성산업","SAMSUNG IND","SAMSUNG IND","08028"]);
    await dtl_ListRes.setRowPosition(0);

    // 삭제 $c.cm.ShowWin(grd_Grid); // 그리드명을 표기
};

/********************************************** 
 * 함수명   : fn_new
 * 설명       : 신규등록을 위한 dataset 세팅 
 ***********************************************/
scwin.new = function() {
    dtl_ListRes.insertRow();
    dtl_ListRes.setCellData(dtl_ListRes.getRowPosition(), "ISUR_CD", scwin.param1);
    dtl_ListRes.setCellData(dtl_ListRes.getRowPosition(), "COM_NM", scwin.param2);

    $c.cm.fn_CtrlBtn("insert");
};

/********************************************** 
 * 함수명   : fn_dup
 * 설명       :  한글기준명 중복검사 
 ***********************************************/
scwin.dup = function() {
    let dupcnt = 0;
    for (let i = 1; i <= dtl_ListRes.getRowCount(); i++) {
        // alert(dts_List.NameString(i, "BAS_ISU_NM") + " " +txb_NEW_BAS_ISU_NM.value);
        if (dtl_ListRes.getCellData(i, "BAS_ISU_NM") === txb_NEW_BAS_ISU_NM.getValue()) {
            dupcnt++;
        }
    }
    // alert("dupcnt " +dupcnt);
    if (dupcnt === 0) {
        return true;
    } // 중복아님 
    else {
        return false;
    } // 중복 

};
